rows.vgi.example_queries:
[
  {
    "description": "Explode a .evtx file at the given path into one row per event record, ordered by record id.",
    "sql": "SELECT record_id, event_id, provider, time_created FROM evtx.main.evtx_records('test/sql/data/sample-security.evtx') ORDER BY record_id;"
  },
  {
    "description": "Label each parsed record with its human-readable meaning by LEFT JOINing the event id reference onto evtx_records (meaning is NULL for ids the reference does not catalogue).",
    "sql": "SELECT r.record_id, r.event_id, ref.name AS meaning, r.time_created FROM evtx.main.evtx_records('test/sql/data/sample-security.evtx') AS r LEFT JOIN evtx.main.windows_event_id_reference AS ref ON ref.event_id = r.event_id AND ref.channel = r.channel ORDER BY r.record_id;"
  },
  {
    "description": "Rank event ids by frequency to surface the noisiest activity in a log.",
    "sql": "SELECT event_id, count(*) AS n FROM evtx.main.evtx_records('test/sql/data/sample-security.evtx') GROUP BY event_id ORDER BY n DESC;"
  }
]

rows.vgi.executable_examples:
[
  {
    "description": "Non-evtx bytes yield zero rows from evtx_records (hostile input is handled, never an error).",
    "sql": "SELECT count(*) AS n FROM evtx.main.evtx_records('not a real evtx'::BLOB)"
  },
  {
    "description": "Non-evtx bytes are reported as not valid (false), never an error.",
    "sql": "SELECT evtx.main.is_valid_evtx('not a real evtx'::BLOB) AS valid"
  },
  {
    "description": "Non-evtx bytes count as zero event records (hostile input is handled).",
    "sql": "SELECT evtx.main.evtx_record_count('not a real evtx'::BLOB) AS records"
  }
]

