[
  {"description": "Count the event records in a .evtx file read as a BLOB.", "sql": "SELECT evtx.main.evtx_record_count((SELECT content FROM read_blob('Security.evtx')));"},
  {"description": "Non-evtx bytes count as 0 records (hostile input is handled, not an error).", "sql": "SELECT evtx.main.evtx_record_count('not a real evtx'::BLOB) AS records;"}
]

[
  {
    "description": "Check whether a file's bytes are a parseable .evtx before processing.",
    "sql": "SELECT evtx.main.is_valid_evtx((SELECT content FROM read_blob('Security.evtx')));"
  },
  {
    "description": "Non-evtx bytes are reported as not valid (false), not an error.",
    "sql": "SELECT evtx.main.is_valid_evtx('not a real evtx'::BLOB) AS valid;"
  },
  {
    "description": "Triage a folder of collected files: flag which ones are parseable .evtx logs and how many event records each holds (non-evtx files show valid = false and 0 records).",
    "sql": "SELECT filename, evtx.main.is_valid_evtx(content) AS valid, evtx.main.evtx_record_count(content) AS records FROM read_blob('test/sql/data/*') ORDER BY filename;"
  }
]
